fn canon_case(r:&Case,clock:Timestamp)->Result<Value>{Ok(json!({"id":json!(r.id.0.to_string()),"project_id":json!(r.project_id.0.to_string()),"unit_id":json!(r.unit_id.0.to_string()),"unit_number":json!(r.unit_number),"unit_state":json!(r.unit_state.as_str()),"attempt_id":r.attempt_id.map_or(Value::Null,|v|json!(v.0.to_string())),"attempt_sequence":json!(r.attempt_sequence),"attempt_state":r.attempt_state.map_or(Value::Null,|v|json!(v.as_str())),"kind":json!(r.kind.as_str()),"subject_revision":json!(r.subject_revision),"state":json!(r.state.as_str()),"opened_at":time(r.opened_at,clock),"resolved_at":r.resolved_at.map_or(Value::Null,|v|time(v,clock)),"failure_id":r.failure_id.map_or(Value::Null,|v|json!(v.0.to_string())),"evidence_id":r.evidence_id.map_or(Value::Null,|v|json!(v.0.to_string())),"origin":json!(r.origin.as_str()),"source_ref":optional(r.source_ref.as_ref(),text)?}))}
fn canon_failure(r:&Failure,clock:Timestamp)->Result<Value>{Ok(json!({"id":json!(r.id.0.to_string()),"attempt_id":json!(r.attempt_id.0.to_string()),"stage":json!(r.stage.as_str()),"code":text(&r.code)?,"reason":text(&r.reason)?,"details":doc(&r.details)?,"log_refs":doc(&r.log_refs)?,"created_at":time(r.created_at,clock)}))}
fn canon_pendingreview(r:&PendingReview,clock:Timestamp)->Result<Value>{Ok(json!({"case_id":json!(r.case_id.0.to_string()),"kind":json!(r.kind.as_str()),"subject_revision":json!(r.subject_revision),"opened_at":time(r.opened_at,clock),"unit_number":json!(r.unit_number),"unit_title":text(&r.unit_title)?,"track_slug":text(&r.track_slug)?,"attempt_sequence":json!(r.attempt_sequence),"verdict":optional(r.verdict.as_ref(),text)?,"failure_stage":r.failure_stage.map_or(Value::Null,|v|json!(v.as_str())),"failure_code":optional(r.failure_code.as_ref(),text)?,"failure_reason":optional(r.failure_reason.as_ref(),text)?,"origin":json!(r.origin.as_str())}))}
